<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('SELECT * FROM admins WHERE email=?');$s->execute([trim($_POST['email']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];go('admin/dashboard.php');}$err='Invalid admin credentials.';}$page_title='Admin Login';require 'includes/header.php';?><div class="form-wrap"><div class="form-card"><span class="eyebrow">STAFF ACCESS</span><h1>Garage command.</h1><p>Manage capacity, sessions, drivers and revenue.</p><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn dark" style="width:100%">Enter admin dashboard →</button></form></div></div><?php require 'includes/footer.php';?>
